import numpy as np,pickle
from rdkit import Chem
idx=pickle.load(open("idx.pkl","rb"))
L=open("opt3.xyz").read().split('\n'); n=int(L[0]); syms=[];X=[]
for l in L[2:2+n]:
    p=l.split(); syms.append(p[0]); X.append([float(v) for v in p[1:]])
X=np.array(X)
ir=idx['ir']
rad={'H':0.31,'C':0.76,'P':1.07}
bonds=[]
for i in range(n):
    for j in range(i+1,n):
        if i==ir or j==ir: continue
        d=np.linalg.norm(X[i]-X[j])
        if d<(rad[syms[i]]+rad[syms[j]])+0.4: bonds.append((i,j,d))
deg={i:0 for i in range(n)}
for i,j,d in bonds: deg[i]+=1; deg[j]+=1
# expected degrees from the rdkit mol
m=Chem.MolFromMolFile("full2.mol",sanitize=False)
print("mol atoms",m.GetNumAtoms())
exp={}
for a in m.GetAtoms():
    nb=[x.GetIdx() for x in a.GetNeighbors() if x.GetIdx()!=ir]
    exp[a.GetIdx()]=set(nb)
got={i:set() for i in range(n)}
for i,j,d in bonds: got[i].add(j); got[j].add(i)
bad=0
for i in range(n):
    if i==ir: continue
    if exp[i]!=got[i]:
        print("MISMATCH",i,syms[i],"exp",sorted(exp[i]),"got",sorted(got[i])); bad+=1
print("mismatches",bad)
from collections import Counter
print(Counter(syms))
EOF
python3 verify.py
